_MUN = None
def _mun():
    global _MUN
    if _MUN is None:
        import json as _j
        _MUN = _j.loads(MUN_JSON)
    return _MUN
_PREF = re.compile(r"^(?:prefeitura(?: municipal)?|camara municipal|municipio|cidade|distrito|comunidade|zona rural)\s+(?:de|da|do)\s+", re.I)
_FIM = re.compile(r"\bem\s+([a-z][a-z ]{2,40})$")
def _kmun(s):
    return re.sub(r"\s+", " ", re.sub(r"[^a-z0-9 ]", " ", N(s).lower())).strip()
def _resolve(k):
    """nome normalizado -> (UF, nome) se o município existe e não é ambíguo (ou se for capital/cidade conhecida)"""
    if k in CAPITAIS: return CAPITAIS[k], NOMES.get(k, k.title())
    if k in OUTRAS: return OUTRAS[k], NOMES.get(k, k.title())
    v = _mun().get(k)
    if v and len(v) == 1:
        uf, nome = next(iter(v.items()))
        if uf != 'DF': return uf, nome
    return None
def _cita_exterior(txt):
    t = " " + _kmun(txt) + " "
    try:
        if any(" " + k + " " in t for k in _IDX if len(k) > 3 and k != "brasil"): return True
        if any(" " + k + " " in t for k in CIDADES_EX): return True
    except NameError:
        pass
    return False
def achar_cidade(txt):
    """acha um município brasileiro no texto do local/assunto.
    Só aceita quando um trecho do texto (separado por - , / | ( ) ·) É o nome da cidade, ou termina com 'em/de <cidade>'.
    Nome que existe em mais de um estado (ex.: Bom Jesus) não é adivinhado: precisa do estado escrito."""
    if not txt: return None
    txt = re.sub(r"\([^)]*\)", " ", txt)          # texto entre parênteses (país, ponto turístico) não é a cidade
    if _cita_exterior(txt): return None              # 'Barcelona', 'Paris - França': é exterior, não município homônimo
    for seg in re.split(r"[-–,/|·;]", txt):
        k = _kmun(_PREF.sub("", N(seg).strip()))
        if not k or k in ('virtual', 'teams'): continue
        r = _resolve(k)
        if r: return r
        m = _FIM.search(k)
        if m:
            r = _resolve(m.group(1).strip())
            if r: return r
    return None
